const timeInfo = await Aboutme.system.getCurrentTime();
const startDate = `${timeInfo.year}-${String(timeInfo.month).padStart(2, '0')}-01`;
const endDate = `${timeInfo.year}-${String(timeInfo.month).padStart(2, '0')}-${String(timeInfo.day).padStart(2, '0')}`;
const result = await Aboutme.plugins.diary.getDiaries({startDate, endDate});
if (result.error) {
  setResult(`错误: ${result.error}`);
} else {
  setResult(`共找到 ${result.total} 篇日记`);
}

const endDate = await Aboutme.system.getCustomDate({format: 'yyyy-MM-dd'});
const startDate = await Aboutme.system.getCustomDate({subtract: {days: 7}, format: 'yyyy-MM-dd'});
const result = await Aboutme.plugins.diary.getDiaries({startDate, endDate});
if (result.error) {
  setResult(`错误: ${result.error}`);
} else {
  const summary = result.diaries.map(d => `${d.date}: ${d.title || '无标题'} (${d.wordCount}字)`).join('\n');
  setResult(summary || '无日记记录');
}

const timeInfo = await Aboutme.system.getCurrentTime();
const startDate = `${timeInfo.year}-01-01`;
const endDate = `${timeInfo.year}-12-31`;
const result = await Aboutme.plugins.diary.getDiaries({startDate, endDate, offset: 0, count: 5});
if (result.error) {
  setResult(`错误: ${result.error}`);
} else {
  setResult(`共 ${result.total} 条,当前显示 ${result.diaries.length} 条,是否有更多: ${result.hasMore}`);
}

const timeInfo = await Aboutme.system.getCurrentTime();
const today = `${timeInfo.year}-${String(timeInfo.month).padStart(2, '0')}-${String(timeInfo.day).padStart(2, '0')}`;
const result = await Aboutme.plugins.diary.getDiary({date: today});
if (result.exists) {
  setResult(`标题: ${result.title}\n内容: ${result.content}\n心情: ${result.mood || '未设置'}\n字数: ${result.wordCount}`);
} else {
  setResult(result.error || '今天还没有日记');
}

const result = await Aboutme.plugins.diary.getDiary({date: '2024-01-01'});
if (result.exists) {
  setResult(JSON.stringify(result, null, 2));
} else {
  setResult('该日期没有日记');
}

const timeInfo = await Aboutme.system.getCurrentTime();
