const result = await Aboutme.plugins.diary.getMonthStats({});
if (result.error) {
  setResult(`错误: ${result.error}`);
} else {
  setResult(`${result.year}年${result.month}月统计：\n` +
    `总字数: ${result.wordCount}\n` +
    `完成天数: ${result.completedDays}/${result.totalDays}\n` +
    `完成度: ${result.progress}%`);
}

