} else {
  setResult('未找到该日期的日记');
}

const diary = await Aboutme.plugins.diary.findDiaryByDate({date: '2025-01-15'});
if (diary) {
  setResult(`日记标题: ${diary.title || '无标题'}, 内容: ${diary.content.substring(0, 50)}...`);
} else {
  setResult('该日期没有日记');
}

const diaries = await Aboutme.plugins.diary.findDiaryByTitle({title: '工作', fuzzy: true, findAll: true});
const totalWords = diaries.reduce((sum, d) => sum + (d.wordCount || 0), 0);
setResult(`找到 ${diaries.length} 篇包含'工作'的日记，共 ${totalWords} 字`);
